BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE actor uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();domain uuid;other_domain uuid;link uuid;key uuid;d jsonb;r jsonb;pref jsonb;old_pref jsonb;old_version uuid;context_before jsonb;job_before jsonb;image_before jsonb;before_events bigint;linked jsonb;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(outsider);INSERT INTO public.user_roles VALUES(actor,'admin');
 d:=public.redirect_domain_resource('create',actor,p_values=>'{"hostname":"archive-a.community.com"}');domain:=(d->>'id')::uuid;
 r:=public.redirect_domain_resource('create',actor,p_values=>'{"hostname":"archive-b.community.com"}');other_domain:=(r->>'id')::uuid;
 UPDATE public.redirect_domains SET ownership_state='verified',verified_at=now(),verified_until=now()+interval '1 day',provider_id='archive-fixture',routing_provider_id='archive-fixture',routing_protocol=1,routing_seen_at=now() WHERE id=domain;
 INSERT INTO public.redirect_domain_jobs(domain_id,zone_id,cname_target,requested_by,state,provider_status,ssl_status,checked_at) VALUES(domain,repeat('a',32),'links.queer.guide',actor,'ready','active','active',now());
 context_before:=public.redirect_public_domain('archive-a.community.com',true);
 IF context_before IS NULL THEN RAISE EXCEPTION 'Archive fixture lacks routing proof';END IF;
 SELECT to_jsonb(j) INTO job_before FROM public.redirect_domain_jobs j WHERE domain_id=domain;
 r:=public.redirect_management_mutate(jsonb_build_array(jsonb_build_object('operation','create','data',jsonb_build_object('slug','archive-link','target','/private-archive-destination','domainId',domain))),NULL,actor);link:=(r#>>'{0,link,id}')::uuid;
 INSERT INTO public.redirect_api_tokens(name,token_hash,prefix,scopes,redirect_ids,created_by,expires_at) VALUES('Archive read key',repeat('e',64),'fixture',ARRAY['links:read','links:write'],ARRAY[link],actor,now()+interval '1 day') RETURNING id INTO key;
 pref:=public.redirect_domain_preference(actor);old_pref:=public.redirect_domain_preference(actor,jsonb_build_object('version',pref->>'version','domainId',domain));
 PERFORM public.redirect_qr_image_resource('create',actor,p_values=>jsonb_build_object('linkId',link),p_hash=>repeat('a',64));image_before:=public.redirect_public_qr_image(repeat('a',64));
 SELECT count(*) INTO before_events FROM public.redirect_events;
 d:=public.redirect_domain_resource('get',actor,domain);old_version:=(d->>'version')::uuid;
 d:=public.redirect_domain_resource('patch',actor,domain,jsonb_build_object('version',old_version,'archived',true));
 IF NOT(d->>'archived')::boolean OR(d->>'disabled')::boolean OR NOT(d->>'routingReady')::boolean OR(d->>'version')::uuid=old_version THEN RAISE EXCEPTION 'Archive disabled routing or failed to version metadata';END IF;
 IF public.redirect_public_domain('archive-a.community.com',true) IS DISTINCT FROM context_before OR(SELECT to_jsonb(j) FROM public.redirect_domain_jobs j WHERE domain_id=domain) IS DISTINCT FROM job_before THEN RAISE EXCEPTION 'Archive altered routing/provider lifecycle';END IF;
 IF public.redirect_public_qr_image(repeat('a',64)) IS DISTINCT FROM image_before OR public.redirect_management_link(link)->>'shortUrl'<>'https://archive-a.community.com/archive-link' THEN RAISE EXCEPTION 'Archive changed an existing link/image target';END IF;
 IF (public.redirect_domain_choices()->>'count')::integer<>0 OR(public.redirect_domain_choices(key)->>'count')::integer<>0 THEN RAISE EXCEPTION 'Archived domain remained in owner/key new-link choices';END IF;
 linked:=public.redirect_linked_domains(key);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(linked->'data') item WHERE item->>'id'=domain::text) THEN RAISE EXCEPTION 'Archive removed existing-link inventory domain facet';END IF;
 pref:=public.redirect_domain_preference(actor);
 IF pref->>'domainId' IS NOT NULL OR pref->>'version'=old_pref->>'version' THEN RAISE EXCEPTION 'Archive did not clear/version the primary default';END IF;
 BEGIN PERFORM public.redirect_domain_preference(actor,jsonb_build_object('version',old_pref->>'version','domainId',domain));RAISE EXCEPTION 'Stale primary resurrected archived domain';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM public.redirect_domain_preference(actor,jsonb_build_object('version',pref->>'version','domainId',domain));RAISE EXCEPTION 'Archived primary accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 r:=public.redirect_domain_resource('list',actor);
 IF (r->>'count')::integer<>1 OR r#>>'{data,0,id}'<>other_domain::text THEN RAISE EXCEPTION 'Default owner list includes archived domains';END IF;
 r:=public.redirect_domain_resource('list',actor,p_values=>'{"archive":"archived","q":"ARCHIVE-A"}');
 IF (r->>'count')::integer<>1 OR r#>>'{data,0,id}'<>domain::text OR r->>'nextCursor' IS NOT NULL THEN RAISE EXCEPTION 'Archive/search filter incorrect';END IF;
 IF(public.redirect_domain_resource('list',actor,p_values=>'{"archive":"all","q":"%"}')->>'count')::integer<>0 THEN RAISE EXCEPTION 'Search wildcard became a pattern';END IF;
 r:=public.redirect_domain_resource('list',actor,p_values=>'{"archive":"all"}',p_limit=>1);
 IF (r->>'count')::integer<>2 OR r->>'nextCursor' IS NULL THEN RAISE EXCEPTION 'Filtered pagination omitted rows';END IF;
 r:=public.redirect_domain_resource('list',actor,p_values=>'{"archive":"all"}',p_limit=>1,p_after=>(r->>'nextCursor')::uuid);
 IF jsonb_array_length(r->'data')<>1 OR r->>'nextCursor' IS NOT NULL THEN RAISE EXCEPTION 'Filtered pagination did not advance';END IF;
 BEGIN PERFORM public.redirect_domain_resource('patch',actor,domain,jsonb_build_object('version',old_version,'archived',false));RAISE EXCEPTION 'Stale restoration accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM public.redirect_domain_resource('patch',outsider,domain,jsonb_build_object('version',d->>'version','archived',false));RAISE EXCEPTION 'Non-owner restored domain';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_domain_resource('patch',actor,domain,jsonb_build_object('version',d->>'version','archived','true'));RAISE EXCEPTION 'String archive state accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.redirect_domain_resource('list',actor,p_values=>'{"archive":null}');RAISE EXCEPTION 'Invalid archive filter accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 -- Explicit-ID edits retain current link authorization while archived; archive is not disable.
 r:=public.redirect_management_mutate(jsonb_build_array(jsonb_build_object('operation','update','id',link,'data',jsonb_build_object('target','/archive-updated'))),NULL,actor);
 IF r#>>'{0,link,domainId}'<>domain::text THEN RAISE EXCEPTION 'Editing an archived-domain link moved it';END IF;
 d:=public.redirect_domain_resource('patch',actor,domain,jsonb_build_object('version',d->>'version','archived',false));
 IF(d->>'archived')::boolean OR(public.redirect_domain_choices()->>'count')::integer<>1 OR public.redirect_domain_preference(actor)->>'domainId' IS NOT NULL THEN RAISE EXCEPTION 'Restore failed or silently reset primary';END IF;
 IF (SELECT count(*) FROM public.redirect_events)<>before_events THEN RAISE EXCEPTION 'Domain maintenance recorded visits';END IF;
 IF has_function_privilege('anon','public.redirect_domain_archive_primary()','EXECUTE') OR has_table_privilege('authenticated','public.redirect_domains','UPDATE') THEN RAISE EXCEPTION 'Archive grants exposed private state';END IF;
END $$;
ROLLBACK;
